(267, 15, 'Rigid Steel Conduit (RSC) provides the highest level of protection against severe physical damage.', 'true_false'),
(268, 15, 'Electrical Metallic Tubing (EMT) can be easily threaded using a standard pipe threader.', 'true_false'),
(269, 15, 'Intermediate Metal Conduit (IMC) was designed to be a heavier and more expensive alternative to RSC.', 'true_false'),
