--
-- Triggers `tbl_trainer`
--
DELIMITER $$
CREATE TRIGGER `trg_trainer_before_delete` BEFORE DELETE ON `tbl_trainer` FOR EACH ROW BEGIN
    SELECT COUNT(*) INTO @batch_count 
    FROM tbl_batch 
    WHERE trainer_id = OLD.trainer_id 
    AND status IN ('open', 'ongoing');
    
    IF @batch_count > 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'Cannot delete trainer with active batches';
    END IF;
END
$$
DELIMITER ;

